update_md5_placeholder.find_text:
// Handle Enter/Return
if (key.return) {
  if (multiline && key.shift) {
    // Shift+Enter in multiline mode inserts newline
    const result = insertText(input, cursorPosition, "\n");
    const { text: capped, position } = capToMaxLength(result.text, result.position, onTruncated);
    setInputState(capped);
    setCursorPositionState(position);
    setOriginalInput(capped);
  } else {
    handleSubmit();
  }
  return;
}

update_md5_placeholder.content_md5_placeholder:
// Handle Enter/Return
const isEnter =
  !!key.return ||
  key.name === "return" ||
  inputChar === "\r" ||
  inputChar === "\n";
if (isEnter) {
  if (multiline && key.shift) {
    // Shift+Enter in multiline mode inserts newline
    const result = insertText(input, cursorPosition, "\n");
    const { text: capped, position } = capToMaxLength(
      result.text,
      result.position,
      onTruncated
    );
    setInputState(capped);
    setCursorPositionState(position);
    setOriginalInput(capped);
  } else {
    handleSubmit();
  }
  return;
}

// When debugging input, also log state transitions (captures whether input updates between key events).
useEffect(() => {
  if (!process.env.GROK_DEBUG_INPUT) return;

  try {
    const logPath =
      process.env.GROK_DEBUG_INPUT_FILE ||
      path.join(process.cwd(), "logs", "input_debug.jsonl");
    fs.mkdirSync(path.dirname(logPath), { recursive: true });
    fs.appendFileSync(
      logPath,
      JSON.stringify(
        {
          t: new Date().toISOString(),
          type: "state",
          inputLen: input.length,
          cursorPosition,
        },
        null,
        0
      ) + "\n",
      "utf8"
    );
  } catch {
    // ignore debug logging failures
  }
}, [input, cursorPosition]);

